package cn.bidcheck.verification.engine;

import cn.bidcheck.verification.facts.TableStructure;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;
import org.junit.jupiter.api.Test;
import static cn.bidcheck.verification.engine.VerificationTypes.*;
import static org.junit.jupiter.api.Assertions.*;

class NativePdfTableBindingTest {
    @com.fasterxml.jackson.annotation.JsonAutoDetect(fieldVisibility = com.fasterxml.jackson.annotation.JsonAutoDetect.Visibility.ANY, getterVisibility = com.fasterxml.jackson.annotation.JsonAutoDetect.Visibility.NONE, isGetterVisibility = com.fasterxml.jackson.annotation.JsonAutoDetect.Visibility.NONE)
    static final class Fixture {
        private final EvidenceCorpus corpus;
        private final List<Map<String,Object>> cells;
        private final String id;
        @com.fasterxml.jackson.annotation.JsonCreator
        Fixture(@com.fasterxml.jackson.annotation.JsonProperty("corpus") EvidenceCorpus corpus, @com.fasterxml.jackson.annotation.JsonProperty("cells") List<Map<String,Object>> cells, @com.fasterxml.jackson.annotation.JsonProperty("id") String id) { this.corpus = corpus; this.cells = cells; this.id = id; }
        public EvidenceCorpus corpus() { return corpus; }
        public List<Map<String,Object>> cells() { return cells; }
        public String id() { return id; }
        @Override public boolean equals(Object other) { if (this == other) return true; if (other == null || getClass() != other.getClass()) return false; Fixture that = (Fixture) other; return java.util.Objects.equals(this.corpus, that.corpus) && java.util.Objects.equals(this.cells, that.cells) && java.util.Objects.equals(this.id, that.id); }
        @Override public int hashCode() { int hash = 0; hash = 31 * hash + java.util.Objects.hashCode(this.corpus); hash = 31 * hash + java.util.Objects.hashCode(this.cells); hash = 31 * hash + java.util.Objects.hashCode(this.id); return hash; }
        @Override public String toString() { return "Fixture[" + "corpus=" + corpus + ", cells=" + cells + ", id=" + id + "]"; }
}
    Fixture fixture(){String id=SourceBoundRecordNormalizationTest.id(),prefix=id.substring(0,13),suffix=id.substring(13);String text="本项目人员配置\n姓名 测试甲 年龄 35\n职称 工程师 身份证号 "+prefix+" 拟在本合同任职 项目负责人\n"+suffix+"\n毕业学校 测试学院";EvidenceCorpus corpus=new PersonnelCountRoleTest().corpus(text);List<Map<String,Object>> cells=new ArrayList<>();
        cells.add(cell(corpus,"name-label",1,1,"姓名",true,cn.bidcheck.compat.Java8Api.listOf(),cn.bidcheck.compat.Java8Api.listOf("姓名")));cells.add(cell(corpus,"name",1,2,"测试甲",false,cn.bidcheck.compat.Java8Api.listOf("name-label"),cn.bidcheck.compat.Java8Api.listOf("测试甲")));
        cells.add(cell(corpus,"id-label",2,3,"身份证号",true,cn.bidcheck.compat.Java8Api.listOf(),cn.bidcheck.compat.Java8Api.listOf("身份证号")));cells.add(cell(corpus,"id",2,4,prefix+"\n"+suffix,false,cn.bidcheck.compat.Java8Api.listOf("id-label"),cn.bidcheck.compat.Java8Api.listOf(prefix, suffix)));
        cells.add(cell(corpus,"role-label",2,5,"拟在本合同任职",true,cn.bidcheck.compat.Java8Api.listOf(),cn.bidcheck.compat.Java8Api.listOf("拟在本合同任职")));cells.add(cell(corpus,"role",2,6,"项目负责人",false,cn.bidcheck.compat.Java8Api.listOf("role-label"),cn.bidcheck.compat.Java8Api.listOf("项目负责人")));return new Fixture(corpus,cells,id);
    }
    Map<String,Object> cell(EvidenceCorpus corpus,String id,int row,int col,String text,boolean header,List<String> headers,List<String> fragments){Source s=corpus.all.get(0);String page=s.evidence().quote();List<Map<String,Object>> refs=new ArrayList<>();int cursor=0;for(String part:fragments){int start=page.indexOf(part,cursor);assertTrue(start>=0);refs.add(linked("text",part,"start",start,"end",start+part.length()));cursor=start+part.length();}return linked("kind","TABLE_CELL","cellId",id,"spanId",id,"source","PDFBOX_NATIVE_TABLE","documentId",s.evidence().documentId(),"documentHash",s.documentHash(),"documentVersion",1,"locationType","PAGE","location",1,"tableId","grid","tableType","KEY_VALUE","row",row,"column",col,"rowSpan",1,"columnSpan",1,"text",text,"header",header,"headerCellIds",headers,"coordinateSpace","PDF_DISPLAY_POINTS_TOP_LEFT","pageWidth",700,"pageHeight",800,"bbox",cn.bidcheck.compat.Java8Api.listOf(col*80, row*40, col*80+70, row*40+35),"sourceFragments",refs);}
    List<Map<String,Object>> sources(Fixture f){return LayoutBinding.sources(role(f),f.corpus.byId);}
    Fact role(Fixture f){return new Fact("role","PERSON_ROLE","项目负责人","姓名","测试甲","测试甲","","","CURRENT_PROJECT",cn.bidcheck.compat.Java8Api.toList(f.corpus.all.stream().map(Source::id)),cn.bidcheck.compat.Java8Api.mapOf("cellIds", cn.bidcheck.compat.Java8Api.listOf("name", "id", "role")));}
    @Test void splitNativeCellIgnoresInterleavedOtherColumnTextAndBindsExplicitKeyValueRecord(){cn.bidcheck.verification.engine.NativePdfTableBindingTest.Fixture f=fixture();assertFalse(f.corpus.all.get(0).evidence().quote().contains(f.id));cn.bidcheck.verification.facts.TableStructure.Result result=TableStructure.analyze("测试甲",cn.bidcheck.compat.Java8Api.listOf("name", "id", "role"),f.cells,sources(f));assertTrue(result.valid(),result.toString());assertEquals("项目负责人",result.rows().get(0).fields().get("ROLE"));assertTrue(result.rows().get(0).strongIdentity());cn.bidcheck.verification.engine.ProofVerifier.Verified verified=new ProofVerifier(f.corpus.byId).verify(new ObjectMapper().valueToTree(cn.bidcheck.compat.Java8Api.mapOf("facts", cn.bidcheck.compat.Java8Api.listOf(role(f)))),f.corpus.all,f.cells);assertTrue(verified.rejected().isEmpty(),verified.rejected().toString());assertEquals(1,verified.facts().size());}
    @Test void fragmentOffsetOrPageGeometryCannotBeInvented(){for(boolean offset:cn.bidcheck.compat.Java8Api.listOf(true, false)){cn.bidcheck.verification.engine.NativePdfTableBindingTest.Fixture f=fixture();java.util.Map<java.lang.String, java.lang.Object> value=f.cells.stream().filter(c->c.get("cellId").equals("id")).findFirst().orElseThrow(java.util.NoSuchElementException::new);if(offset){java.util.List<java.util.Map<java.lang.String, java.lang.Object>> fragments=RuleEvaluator.maps(value.get("sourceFragments"));java.util.ArrayList<java.util.Map<java.lang.String, java.lang.Object>> modified=new ArrayList<Map<String,Object>>();for(java.util.Map<java.lang.String, java.lang.Object> part:fragments){Map<String,Object> p=new LinkedHashMap<>(part);p.put("start",((Number)p.get("start")).intValue()+1);p.put("end",((Number)p.get("end")).intValue()+1);modified.add(p);}value.put("sourceFragments",modified);}else value.put("bbox",cn.bidcheck.compat.Java8Api.listOf(-10, 0, 20, 30));assertFalse(TableStructure.analyze("测试甲",cn.bidcheck.compat.Java8Api.listOf("name", "id", "role"),f.cells,sources(f)).valid());}}
    @Test void keyValueBindingRequiresOnePersonAndCannotInheritAnotherName(){cn.bidcheck.verification.engine.NativePdfTableBindingTest.Fixture f=fixture();java.util.LinkedHashMap<java.lang.String, java.lang.Object> extra=new LinkedHashMap<>(f.cells.get(1));extra.put("cellId","second-name");extra.put("spanId","second-name");extra.put("column",3);extra.put("headerCellIds",cn.bidcheck.compat.Java8Api.listOf("name-label"));java.util.LinkedHashMap<java.lang.String, java.lang.Object> label=new LinkedHashMap<>(f.cells.get(0));label.put("cellId","second-label");label.put("spanId","second-label");label.put("column",2);extra.put("headerCellIds",cn.bidcheck.compat.Java8Api.listOf("second-label"));f.cells.add(label);f.cells.add(extra);assertEquals("STRUCTURE_KEY_VALUE_OWNER_AMBIGUOUS",TableStructure.analyze("测试甲",cn.bidcheck.compat.Java8Api.listOf("name", "id", "role"),f.cells,sources(f)).issue());}
    @Test void keyValueNameLabelCannotLeakIntoUnlabelledRowsBelow(){cn.bidcheck.verification.engine.NativePdfTableBindingTest.Fixture f=fixture();f.cells.add(cell(f.corpus,"school-label",3,1,"毕业学校",false,cn.bidcheck.compat.Java8Api.listOf(),cn.bidcheck.compat.Java8Api.listOf("毕业学校")));f.cells.add(cell(f.corpus,"school",3,2,"测试学院",false,cn.bidcheck.compat.Java8Api.listOf(),cn.bidcheck.compat.Java8Api.listOf("测试学院")));cn.bidcheck.verification.facts.TableStructure.Result result=TableStructure.analyze("测试甲",cn.bidcheck.compat.Java8Api.listOf("name", "id", "role"),f.cells,sources(f));assertTrue(result.valid(),result.toString());assertEquals(1,result.rows().size());assertTrue(result.rows().get(0).strongIdentity());}
}
